body.script:
import EpoxyTransport from 'https://jsdelivr.net';

const form = document.getElementById('searchForm');
const queryInput = document.getElementById('query');
const wispInput = document.getElementById('wispUrl');
const statusEl = document.getElementById('status');
const viewport = document.getElementById('viewport');
const homeBtn = document.getElementById('homeBtn');

if (localStorage.getItem('custom_wisp_url')) {
  wispInput.value = localStorage.getItem('custom_wisp_url');
}

homeBtn.addEventListener('click', function() {
  viewport.style.display = 'none';
  homeBtn.style.display = 'none';
  viewport.src = 'about:blank';
});

function formatTargetUrl(input) {
  const trimmed = input.trim();
  if (/^https?:\/\//i.test(trimmed)) return trimmed;
  if (/^[a-z0-9-]+(\.[a-z0-9-]+)+/i.test(trimmed)) return 'https://' + trimmed;
  return 'https://google.com' + encodeURIComponent(trimmed);
}

form.addEventListener('submit', async function(e) {
  e.preventDefault();
  const wispServer = wispInput.value.trim();
  localStorage.setItem('custom_wisp_url', wispServer);

  const targetUrl = formatTargetUrl(queryInput.value);
  statusEl.textContent = 'Connecting to Wisp backend...';

  try {
    const transport = new EpoxyTransport({ wisp: wispServer });
    await transport.init();

    const response = await transport.request(
      new URL(targetUrl),
      'GET',
      new Headers({ 'User-Agent': navigator.userAgent }),
      null
    );

    const html = await response.body.text();
    const baseTag = '<base href="' + targetUrl + '" />';
    const patchedHtml = html.replace(/<head[^>]*>/i, match => match + baseTag);

    const blob = new Blob([patchedHtml], { type: 'text/html' });
    viewport.src = URL.createObjectURL(blob);
    viewport.style.display = 'block';
    homeBtn.style.display = 'block';
    statusEl.textContent = '';
  } catch (err) {
    statusEl.textContent = 'Error: ' + err.message;
  }
});
